<script setup>
import {ref,computed,onMounted,nextTick} from 'vue'
import {request} from './client'
import Icon from '../Icon.vue'
import {notificationTime} from '../shared/notificationTime.js'
const props=defineProps({institutesOnly:Boolean})
const editor=ref(null),planChoice=ref(''),planReason=ref(''),planNote=ref('')
const campuses=ref([]),site=ref(''),kind=ref(props.institutesOnly?'Institute':'All'),state=ref('All'),query=ref(''),result=ref(null),record=ref(null)
const busy=ref(false),error=ref(''),selected=ref(''),section=ref('connections'),title=ref(null)
const sections={connections:'Connections',classes:'Classes',people:'People',activity:'Attendance',invitations:'Invitations',subscription:'Subscription'}
const totals=computed(()=>['Student','Teacher','Institute'].map(kind=>({kind,total:campuses.value.filter(c=>c.available).flatMap(c=>c.counts).filter(c=>c.kind===kind).reduce((n,c)=>n+Number(c.total),0)})))
const partial=computed(()=>campuses.value.some(c=>!c.available))
const date=value=>value?notificationTime(value):'Not recorded'
const shortDate=value=>value?String(value).slice(0,10):'—'
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(page=0){await run(async()=>{record.value=null;selected.value='';result.value=null;result.value=await request('owner_people','directory',{site:site.value,kind:kind.value,state:state.value,query:query.value,page},'GET')})}
async function refresh(){await run(async()=>{const data=await request('owner_people','overview',{},'GET');campuses.value=data.campuses;if(!site.value)site.value=campuses.value.find(c=>c.available)?.site||''});if(site.value)await load()}
async function open(user,tab=props.institutesOnly?'subscription':'connections',page=0){editor.value=null;planNote.value='';await run(async()=>{record.value=null;selected.value=user;section.value=tab;record.value=await request('owner_people','detail',{site:site.value,user,section:tab,page},'GET')});await nextTick();title.value?.focus()}
async function back(){editor.value=null;planNote.value='';selected.value='';record.value=null;error.value='';await nextTick();title.value?.focus()}
function filter(value){kind.value=value;load()}
function editPlan(row){editor.value={...row};planChoice.value=row.next_plan||row.plan;planReason.value='';planNote.value=''}
async function savePlan(){
 if(!editor.value||!planReason.value.trim()||busy.value)return
 if(!window.confirm(`Save ${planChoice.value} for ${record.value.person.display_name}? Active paid periods keep their current plan until renewal. Unpaid invoice offers will be replaced when the plan changes.`))return
 const target=editor.value
 await run(async()=>{
  const response=await request('owner_people','change_institute_plan',{site:site.value,user:selected.value,subscription:target.name,plan:planChoice.value,expected_modified:target.modified,reason:planReason.value.trim()})
  planNote.value=response.message;editor.value=null
  record.value=await request('owner_people','detail',{site:site.value,user:selected.value,section:'subscription',page:0},'GET')
 })
}
onMounted(refresh)
</script>
<template>
<section class="people-report" aria-label="People and connections">
 <div v-if="!selected&&!institutesOnly" class="directory-intro">
  <div class="count-strip" aria-label="Account totals across reporting campuses"><button v-for="item in totals" :key="item.kind" @click="filter(item.kind)" :disabled="busy" :aria-pressed="kind===item.kind"><span>{{item.kind==='Institute'?'Institutes':item.kind+'s'}}</span><strong>{{campuses.length?item.total:'—'}}</strong><Icon name="ArrowUpRight" :size="18"/></button></div>
  <p class="caption">{{partial?'Partial totals: one or more campuses are unavailable. ':' '}}Accounts counted once within each campus, including pending and disabled accounts. The same email on different campuses counts separately.</p>
 </div>
 <div v-if="error" class="report-error" role="alert"><Icon name="CircleHelp" :size="19"/><div>{{error}}<button :disabled="busy" @click="selected?open(selected,section):refresh()">Try again</button></div></div>
 <p v-if="busy" class="loading" role="status"><Icon name="Hourglass" :size="18"/>Loading campus records…</p>
 <template v-if="!selected">
  <form class="filters" @submit.prevent="load()">
   <label>Campus<select v-model="site" :disabled="busy" @change="load()"><option v-for="c in campuses" :key="c.site" :value="c.site">{{c.site}}{{c.available?'':' · unavailable'}}</option></select></label>
   <label class="people-search">Find an account<div><Icon name="Search" :size="18"/><input v-model="query" type="search" maxlength="120" placeholder="Name, email, username or SISU ID"/></div></label>
   <label>Account status<select v-model="state" :disabled="busy" @change="load()"><option>All</option><option>Enabled</option><option>Disabled</option></select></label>
   <button class="button primary" :disabled="busy||!site">Search</button>
  </form>
  <div class="list-toolbar"><div v-if="!institutesOnly" class="role-filters" aria-label="Account type"><button v-for="v in ['All','Student','Teacher','Institute']" :key="v" :aria-pressed="kind===v" :class="{selected:kind===v}" :disabled="busy" @click="filter(v)">{{v==='All'?'Everyone':v+'s'}}</button></div><button class="button subtle" :disabled="busy" @click="refresh"><Icon name="RotateCcw" :size="16"/>Refresh</button></div>
  <h2 ref="title" tabindex="-1" class="list-title">{{result?.total??0}} {{result?.total===1?'account':'accounts'}}<span v-if="result"> in {{result.site}}</span></h2>
  <div v-if="result?.rows.length" class="table-wrap"><table><thead><tr><th scope="col">Name & account</th><th scope="col">Role</th><th scope="col">Status</th><th scope="col">Last sign-in</th><th scope="col"><span class="sr-only">Details</span></th></tr></thead><tbody><tr v-for="p in result.rows" :key="p.user"><td><strong>{{p.display_name}}</strong><span>{{p.user}}</span><small v-if="p.lms_id||p.username">{{p.lms_id}} {{p.username?'· @'+p.username:''}}</small></td><td>{{p.kind}}</td><td><span class="status" :class="{good:p.enabled}">{{p.enabled?'Enabled':'Disabled'}}</span><small>{{p.profile_status||'No public profile'}}</small></td><td>{{date(p.last_login)}}</td><td><button class="row-action" :aria-label="'View '+p.display_name" @click="open(p.user)">{{institutesOnly?'Manage plan':'View details'}} <Icon name="ArrowRight" :size="16"/></button></td></tr></tbody></table></div>
  <div v-else-if="!busy&&!error" class="empty"><Icon name="Users" :size="30"/><h3>{{site?'No accounts match your filters':'No reporting campuses configured'}}</h3><p>{{site?'Try another name, role or account status.':'Configure campus reporting to view your community.'}}</p></div>
  <div v-if="result" class="pagination"><span>Page {{result.page+1}}</span><button class="button subtle" :disabled="busy||result.page===0" @click="load(result.page-1)">Previous</button><button class="button subtle" :disabled="busy||!result.has_next" @click="load(result.page+1)">Next</button></div>
 </template>
 <template v-else>
  <button class="back" :disabled="busy" @click="back"><Icon name="ChevronLeft" :size="17"/>Back to accounts</button>
  <template v-if="record">
   <header class="person-header"><span class="person-icon"><Icon :name="record.person.kind==='Institute'?'Building2':record.person.kind==='Teacher'?'GraduationCap':'UserRound'" :size="30"/></span><div><p>{{record.person.kind}}<span class="status" :class="{good:record.person.enabled}">{{record.person.enabled?'Enabled':'Disabled'}}</span></p><h2 ref="title" tabindex="-1">{{record.person.display_name}}</h2><p>{{record.person.user}}</p><p class="caption">{{record.person.lms_id}} {{record.person.username?'· @'+record.person.username:''}}</p></div></header>
   <dl class="identity-dates"><div><dt>Account created</dt><dd>{{date(record.person.joined_at)}}</dd></div><div><dt>Last sign-in</dt><dd>{{date(record.person.last_login)}}</dd></div><div><dt>Profile review</dt><dd>{{record.person.profile_status||'No public profile'}}</dd></div></dl>
   <nav class="detail-tabs" aria-label="Account information"><button v-for="(label,key) in sections" :key="key" :class="{selected:section===key}" :aria-current="section===key?'page':undefined" :disabled="busy" @click="open(selected,key)">{{label}}</button></nav>
   <section v-if="section==='connections'&&record.memberships.length" class="membership-list"><h3>Workspace memberships</h3><p class="caption">A teacher can have a personal workspace and belong to several institutes.</p><div v-for="m in record.memberships" :key="m.name"><Icon name="Building2" :size="19"/><strong>{{m.title}}</strong><span>{{m.role}}</span><span class="status" :class="{good:m.active}">{{m.active?'Active membership':'Inactive membership'}}</span><small>Joined {{shortDate(m.joined_at)}}</small></div><p v-if="record.memberships_truncated">Showing the latest 100 memberships.</p></section>
   <h3 class="detail-heading">{{{connections:'Requests & follows',classes:'Classroom connections',people:record.person.kind==='Student'?'Classmates & connected people':'Connected students & teachers',activity:'Recorded session attendance',invitations:'Teacher invitations',subscription:'Subscription records'}[section]}}</h3>
   <p class="caption" v-if="section==='activity'">Attendance records show participation, not whether someone is online right now. Times are in Sri Lanka time.</p>
   <p class="caption" v-if="section==='people'">People connected through this account’s workspace or classrooms. Disabled memberships and past enrollments are included.</p>
   <div v-if="record.rows.length" class="table-wrap"><table>
    <template v-if="section==='connections'"><thead><tr><th>Connected to</th><th>Connection</th><th>Status</th><th>Updated</th></tr></thead><tbody><tr v-for="r in record.rows" :key="r.name"><td><button class="text-link" @click="open(r.related_user)">{{r.title}}</button></td><td>{{r.relationship}}</td><td>{{r.status}}</td><td>{{date(r.updated_at)}}</td></tr></tbody></template>
    <template v-else-if="section==='classes'"><thead><tr><th>Classroom</th><th>Teacher</th><th>Students</th><th>Sessions</th><th>Status</th></tr></thead><tbody><tr v-for="r in record.rows" :key="r.name"><td><strong>{{r.title}}</strong><span>{{r.institute}} · {{r.owner_type}}</span><small>{{r.subject}}</small></td><td><button v-if="r.teacher_user" class="text-link" @click="open(r.teacher_user)">{{r.teacher}}</button><span v-else>Unassigned</span><small v-if="!r.teacher_assignment_active">Assignment inactive</small></td><td>{{r.students}}</td><td>{{r.sessions}}</td><td>{{r.active?'Active classroom':'Inactive classroom'}}</td></tr></tbody></template>
    <template v-else-if="section==='people'"><thead><tr><th>Person</th><th>Membership role</th><th>Class enrollments</th><th>Membership</th></tr></thead><tbody><tr v-for="r in record.rows" :key="r.user"><td><button class="text-link" @click="open(r.user)">{{r.display_name||r.user}}</button><span>{{r.user}}</span></td><td>{{r.role}}</td><td>{{r.classes}}</td><td>{{r.active?'Active':'Inactive'}}</td></tr></tbody></template>
    <template v-else-if="section==='activity'"><thead><tr><th>Session & class</th><th>Student</th><th>Attendance</th><th>Recorded</th></tr></thead><tbody><tr v-for="r in record.rows" :key="r.name"><td><strong>{{r.session_title}}</strong><span>{{r.classroom}}</span></td><td><button class="text-link" @click="open(r.related_user)">{{r.student}}</button></td><td>{{r.status}}<small>{{r.channel}}</small></td><td>{{date(r.recorded_at)}}</td></tr></tbody></template>
    <template v-else-if="section==='invitations'"><thead><tr><th>Institute & teacher</th><th>Status</th><th>Sent</th><th>Responded</th></tr></thead><tbody><tr v-for="r in record.rows" :key="r.name"><td><strong>{{r.institute}}</strong><span>{{r.invite_email}}</span></td><td>{{r.status}}<small>Expires {{shortDate(r.expires_at)}}</small></td><td>{{date(r.sent_at)}}</td><td>{{date(r.responded_at)}}</td></tr></tbody></template>
    <template v-else><thead><tr><th>Plan</th><th>Account</th><th>Trial ends</th><th>Paid through</th><th>Record</th><th>Manage</th></tr></thead><tbody><tr v-for="r in record.rows" :key="r.name"><td><strong>{{r.plan}}</strong><small v-if="r.next_plan">Next: {{r.next_plan}}</small></td><td>{{r.display_name}}<small>{{r.role}}</small></td><td>{{shortDate(r.trial_until)}}</td><td>{{shortDate(r.paid_until)}}</td><td>{{r.enabled?'Enabled':'Disabled'}}<small v-if="r.cancel_at_end">Cancels at period end</small></td><td><button v-if="r.role==='Institute'&&record.person.kind==='Institute'&&r.enabled" class="row-action" :disabled="busy" @click="editPlan(r)">Manage plan</button></td></tr></tbody></template>
   </table></div>
   <div v-else class="empty compact"><Icon name="Search" :size="26"/><h3>No {{sections[section].toLowerCase()}} records</h3><p>No records were found for this account in this campus.</p></div>
   <p v-if="planNote" role="status">{{planNote}}</p>
   <form v-if="editor&&section==='subscription'" class="plan-editor" @submit.prevent="savePlan">
    <h3>Change plan for {{record.person.display_name}}</h3>
    <p>Current plan: {{editor.plan}}<span v-if="editor.next_plan"> · Next plan: {{editor.next_plan}}</span></p>
    <p>Trial and paid-through dates stay the same. During an active paid period, your selection applies at renewal. Otherwise it applies immediately. Changing plans replaces unpaid invoice offers; it does not approve a payment.</p>
    <label>Subscription plan<select v-model="planChoice" :disabled="busy"><option v-for="p in ['Individual','Silver','Gold','Platinum']" :key="p">{{p}}</option></select></label>
    <label>Reason for change<input v-model="planReason" required maxlength="500" :disabled="busy" placeholder="For example: requested by institute owner"/></label>
    <button class="button primary" :disabled="busy||!planReason.trim()">{{busy?'Saving…':'Save plan'}}</button>
    <button type="button" class="button subtle" :disabled="busy" @click="editor=null">Cancel</button>
   </form>
   <div class="pagination"><span>Page {{record.page+1}}</span><button class="button subtle" :disabled="busy||!record.page" @click="open(selected,section,record.page-1)">Previous</button><button class="button subtle" :disabled="busy||!record.has_next" @click="open(selected,section,record.page+1)">Next</button></div>
  </template>
 </template>
</section>
</template>
<style scoped>
.plan-editor{margin:24px 0;padding:24px;border:1px solid #ded3ee;border-radius:16px}.plan-editor label{display:grid;gap:8px;margin:16px 0}.plan-editor p{line-height:1.6}.plan-editor input,.plan-editor select{padding:12px;border:1px solid #ded3ee;border-radius:8px}.plan-editor button{margin-right:12px}

.people-report{--text-secondary:#665c76;color:var(--ink);font-size:14px}.caption{color:var(--text-secondary);font-size:13px;line-height:1.65;margin:12px 0 22px;max-width:90ch}.count-strip{display:flex;border-block:1px solid var(--line);padding:8px 0}.count-strip button{display:flex;gap:16px;align-items:center;flex:1;padding:20px 24px;border:0;border-right:1px solid var(--line);background:none;color:var(--ink);cursor:pointer;text-align:left}.count-strip button:first-child{padding-left:0}.count-strip button:last-child{border-right:0}.count-strip strong{font-size:30px;font-variant-numeric:tabular-nums;margin-left:auto}.count-strip svg{color:var(--owner-purple)}.count-strip button:hover,.count-strip button[aria-pressed=true]{color:var(--owner-purple)}.filters{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin:26px 0 22px}.filters label{display:flex;flex-direction:column;gap:7px;font-weight:600;flex:1;min-width:160px}.filters .people-search{flex:2;min-width:240px}.filters input,.filters select{font:inherit;font-weight:400;width:100%;height:46px;border:1px solid #c7badb;border-radius:8px;background:white;color:var(--ink);padding:0 12px;box-sizing:border-box}.people-search>div{position:relative}.people-search svg{position:absolute;left:12px;top:14px;color:var(--text-secondary)}.filters .people-search input{padding-left:40px}.filters input::placeholder{color:var(--text-secondary)}.filters .button{margin:0;min-height:46px}.list-toolbar{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:22px}.role-filters,.detail-tabs{display:flex;gap:6px;flex-wrap:wrap}.role-filters button,.detail-tabs button{border:1px solid transparent;background:none;padding:10px 14px;color:var(--text-secondary);border-radius:8px;font:inherit;cursor:pointer}.role-filters button.selected,.detail-tabs button.selected{color:#552b91;background:#eee7f6;border-color:#ddd0ef;font-weight:650}.list-title{font-size:17px;margin:0 0 14px}.list-title span{font-size:13px;font-weight:400;color:var(--text-secondary);overflow-wrap:anywhere}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:white}.table-wrap table{border-collapse:collapse;width:100%;min-width:650px;font-size:13px}.table-wrap th{text-align:left;background:#f7f4fa;color:#51455f;font-weight:650;padding:14px 18px}.table-wrap td{padding:17px 18px;border-top:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere;max-width:320px}.table-wrap td strong{display:block;font-size:14px}.table-wrap td>span:not(.status),.table-wrap small{display:block;margin-top:5px;color:var(--text-secondary);font-size:12px}.table-wrap tbody tr:hover{background:#fcfaff}.row-action,.text-link,.back{display:inline-flex;align-items:center;gap:8px;font:inherit;border:0;background:none;color:var(--owner-purple);cursor:pointer;padding:0;text-align:left;min-height:30px}.row-action{white-space:nowrap;font-weight:600}.text-link:hover,.back:hover{text-decoration:underline}.status{display:inline-flex;background:#f0edf3;color:#62576d;font-size:12px;padding:4px 9px;border-radius:6px}.status.good{background:#e7f3eb;color:#226443}.pagination{display:flex;gap:10px;align-items:center;justify-content:flex-end;margin-top:18px}.pagination>span{margin-right:auto;color:var(--text-secondary);font-size:13px}.people-report .button{display:inline-flex;align-items:center;gap:8px;min-height:40px}.empty{padding:44px 24px;border:1px dashed #d6c8e6;border-radius:12px;background:#faf8fd;text-align:center;color:var(--text-secondary)}.empty svg{color:var(--owner-purple)}.empty h3{font-size:17px;color:var(--ink);margin:14px 0 8px}.empty p{margin:0}.compact{padding:30px}.person-header{display:flex;gap:20px;align-items:center;margin:28px 0}.person-icon{display:flex;align-items:center;justify-content:center;width:64px;height:64px;background:#eee7f6;color:var(--owner-purple);border-radius:16px;flex-shrink:0}.person-header h2{font-size:26px;margin:6px 0;overflow-wrap:anywhere}.person-header p{margin:4px 0;color:var(--text-secondary);overflow-wrap:anywhere}.person-header .status{margin-left:12px}.identity-dates{display:flex;gap:32px;flex-wrap:wrap;padding:20px 0;border-block:1px solid var(--line);margin-bottom:24px}.identity-dates dt{color:var(--text-secondary);font-size:12px}.identity-dates dd{margin:6px 0 0}.detail-tabs{border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:24px}.detail-heading,.membership-list h3{font-size:17px;margin:28px 0 14px}.membership-list>div{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid var(--line)}.membership-list strong{flex:1;min-width:200px}.membership-list svg{color:var(--owner-purple)}.membership-list small{color:var(--text-secondary)}.loading{display:flex;align-items:center;gap:10px;color:var(--owner-purple);padding:14px;background:#f6f1fb;border-radius:8px}.report-error{display:flex;gap:12px;background:#fff0f0;border:1px solid #e6b4b4;color:#942e2e;padding:16px;border-radius:10px;margin-bottom:20px}.report-error button{display:block;color:inherit;background:none;text-decoration:underline;border:0;padding:8px 0 0;font:inherit;cursor:pointer}.people-report button:disabled{opacity:.55;cursor:wait}.people-report button:focus-visible,.people-report input:focus-visible,.people-report select:focus-visible{outline:2px solid var(--owner-purple);outline-offset:3px}.people-report ::selection{background:#e1d2f3}.people-report input{caret-color:var(--owner-purple)}.table-wrap{scrollbar-color:#b8a4d1 #f7f4fa}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(max-width:700px){.count-strip button{padding:16px 10px;gap:6px;flex-wrap:wrap;font-size:12px}.count-strip strong{font-size:24px}.count-strip svg{display:none}.filters{display:grid;grid-template-columns:1fr}.filters label,.filters .people-search{min-width:0}.list-toolbar{align-items:flex-start;flex-wrap:wrap}.person-header{gap:14px}.person-header h2{font-size:22px}.identity-dates{gap:20px}.identity-dates>div{flex:1;min-width:145px}.membership-list>div{gap:10px}.membership-list strong{min-width:160px}.pagination .button{padding:10px 12px}.role-filters button,.detail-tabs button{padding:10px;font-size:13px}}
.people-report .detail-tabs{display:flex;flex-direction:row;gap:6px;align-items:center}.people-report .detail-tabs button{width:auto;margin:0;min-height:44px}.people-report .filters>.button{align-self:flex-end;transform:none;margin:0;height:46px}@media(max-width:600px){.people-report .detail-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.people-report .detail-tabs button{padding:10px 5px;text-align:center;font-size:12px}}
</style>
